 43	struct XrceDiag {
 44		String step = "sin iniciar"; // último paso alcanzado
 45		String agent;
 46		int writes = 0, write_errors = 0, write_bytes = 0;
 47		int reads = 0, read_errors = 0, read_bytes = 0, read_packets = 0;
 48		int netctl_state = -1; // sceNetCtlInetGetState: 0 desconectado ... 3 IP obtenida
