 93	// Inicializa la red de la Vita ANTES de net_udp_init, guardando el código de cada paso (net_udp solo
 94	// devuelve "fallo"). El pool de sceNetInit sale del montón (memalign) y no del array estático de
 95	// net_udp.c: dentro de libgodot.so ese array vive en la imagen que mapea el cargador, no en memoria
 96	// normal de la app (hipótesis de G5 en hardware). net_udp_init acepta la red ya iniciada (EBUSY).
 97	void vita_net_init() {
 98	#ifdef VITA_ENABLED
 99		static void *pool = nullptr;
100		const int POOL = 1024 * 1024;
101		g_diag.rc_sysmodule = sceSysmoduleLoadModule(SCE_SYSMODULE_NET);
102		if (!pool) {
103			pool = memalign(4096, POOL);
104		}
105		if (pool) {
106			SceNetInitParam param;
107			param.memory = pool;
108			param.size = POOL;
109			param.flags = 0;
110			g_diag.rc_netinit = sceNetInit(&param);
111		} else {
112			g_diag.rc_netinit = -1; // sin memoria para el pool
113		}
114		g_diag.rc_netctl = sceNetCtlInit();
115	#endif
116		g_diag.rc_net_udp = net_udp_init();
117	}
