 11	void initialize_ros2_vita_module(ModuleInitializationLevel p_level) {
 12		if (p_level != MODULE_INITIALIZATION_LEVEL_SCENE) {
 13			return;
 14		}
 15		// Mismos nombres que rclgd (docs/17, godot/ros2_vita/API_PARITY.md)
 16		GDREGISTER_CLASS(rclgd);
 17		GDREGISTER_CLASS(RosMsg);
 18		GDREGISTER_CLASS(RosQoS);
 19		GDREGISTER_CLASS(RosNode);
 20		GDREGISTER_ABSTRACT_CLASS(RosPublisher);
 21		GDREGISTER_ABSTRACT_CLASS(RosSubscriber);
 22		GDREGISTER_ABSTRACT_CLASS(RosTimer);
 23	
 24		_rclgd_singleton = memnew(rclgd);
 25		Engine::get_singleton()->add_singleton(Engine::Singleton("rclgd", rclgd::get_singleton()));
 26	}
 27	
 28	void uninitialize_ros2_vita_module(ModuleInitializationLevel p_level) {
 29		if (p_level != MODULE_INITIALIZATION_LEVEL_SCENE) {
 30			return;
 31		}
 32		Engine::get_singleton()->remove_singleton("rclgd");
 33		if (_rclgd_singleton) {
 34			memdelete(_rclgd_singleton);
 35			_rclgd_singleton = nullptr;
 36		}
 37	}

