168		RosTransport *transport = nullptr;
169		Dictionary overrides; // -p clave:=valor
170		Mutex inbox_mutex;
171		List<RxItem> inbox;
172		uint32_t dropped = 0;
173		HashMap<int, ObjectID> subs;
174		Vector<ObjectID> timers;
175		bool pump_connected = false;
176	
177		static void _rx_trampoline(void *p_ctx, int p_sub_id, const uint8_t *p_data, size_t p_len);
178		void _pump();
179		void _ensure_pump();
180	
181	protected:
182		static void _bind_methods();
183	
184	public:
185		static rclgd *get_singleton() { return singleton; }
186		rclgd();
187		~rclgd();
188	
189		Error init(const PackedStringArray &p_args = PackedStringArray());
190		void shutdown();
191		bool ok() const { return running; }
192		Dictionary get_overrides() const { return overrides; }
193		int get_dropped() const { return dropped; }
194		Dictionary get_transport_info() const; // diagnóstico del transporte (XRCE: contadores, WiFi)
195	
196		// Convención de ejes REP-103 <-> Godot (idéntica a rclgd; ver docs/17 §3.3)
197		Vector3 godot_to_ros_vector(const Vector3 &p_v) const { return Vector3(-p_v.z, -p_v.x, p_v.y); }
198		Vector3 ros_to_godot_vector(const Vector3 &p_v) const { return Vector3(-p_v.y, p_v.z, -p_v.x); }
199		Quaternion godot_to_ros_quat(const Quaternion &p_q) const { return Quaternion(-p_q.z, -p_q.x, p_q.y, p_q.w); }
200		Quaternion ros_to_godot_quat(const Quaternion &p_q) const { return Quaternion(-p_q.y, p_q.z, -p_q.x, p_q.w); }
201	
202		// Uso interno de las clases Ros*
203		RosTransport *get_transport() const { return transport; }
204		void register_subscription(int p_id, ObjectID p_obj);
205		void unregister_subscription(int p_id);
206		void register_timer(ObjectID p_obj);
207	};
