  1	// xrce_transport.cpp — transporte micro-ROS (XRCE-DDS) de ros2_vita. Puerta G5 (docs/18 §8).
  2	// Probado en host contra el agente micro-ROS en docker; validado en la Vita 2026-10-30 (G5/G6).
  3	//
  4	// Diseño (el mismo que la app Godot 3.5, que funcionó en hardware):
  5	//  - UN hilo: todo (crear entidades, publicar, atender la sesión) va en el hilo principal. poll()
  6	//    se llama una vez por frame desde rclgd::_pump con uxr_run_session_time(0): envía lo pendiente y
  7	//    vacía los paquetes recibidos SIN bloquear. Así no hacen falta mutex alrededor de la sesión.
  8	//  - Las entidades DDS se crean por XML (las materializa el agente): un participante, un
  9	//    publisher y un subscriber compartidos, y un topic + datawriter/datareader por cada
 10	//    create_publisher/create_subscription.
 11	//  - Dos pares de streams: fiable (QoS RELIABLE, por defecto) y best effort (QoS BEST_EFFORT).
 12	//  - Los bytes ya vienen serializados en CDR por RosMsg (sin la cabecera de encapsulación de
 13	//    4 bytes, que pone el agente): aquí solo se copian.
 14	#include "xrce_transport.h"
 15	
 16	// Mensajes de log SIN tildes: un const char* se convierte a String como Latin-1 (salen "sesiÃ³n").
 17	
 18	#ifdef ROS2_VITA_XRCE // SCsub lo define solo si encuentra las libs XRCE
 19	
 20	#include "core/config/project_settings.h"
 21	#include "core/os/os.h"
 22	#include "core/string/print_string.h"
 23	
 24	#include <uxr/client/client.h>
 25	
 26	extern "C" {
 27	#include "microros_transport.h" // modules/microros-transport (dual C/Rust) -> net-udp
 28	#include "net_udp.h"
 29	}
 30	
 31	#ifdef VITA_ENABLED
 32	#include <malloc.h>
 33	#include <psp2/net/net.h>
 34	#include <psp2/net/netctl.h>
 35	#include <psp2/sysmodule.h>
 36	#endif
 37	
 38	namespace {
 39	
 40	// ---------------------------------------------------------------------------------------------
 41	// Diagnóstico (G5 en hardware): contadores de los 4 callbacks del transporte propio. En la Vita no
 42	// hay consola visible, así que rclgd.get_transport_info() los expone a GDScript para pintarlos.
 43	struct XrceDiag {
 44		String step = "sin iniciar"; // último paso alcanzado
 45		String agent;
 46		int writes = 0, write_errors = 0, write_bytes = 0;
 47		int reads = 0, read_errors = 0, read_bytes = 0, read_packets = 0;
 48		int netctl_state = -1; // sceNetCtlInetGetState: 0 desconectado ... 3 IP obtenida
 49		String vita_ip;
 50		// Códigos de la inicialización de red (Vita): 0 = OK; 0x8041... = errores de sceNet.
 51		int rc_sysmodule = 0, rc_netinit = 0, rc_netctl = 0, rc_net_udp = 0;
 52		int topic_callbacks = 0, topic_dropped = 0; // datos entregados por uxr / descartados aquí
 53		int reliable_full = 0; // publicaciones desviadas al stream best effort por estar lleno el fiable
 54	};
 55	XrceDiag g_diag;
 56	
 57	struct TransportArgs {
 58		const char *ip;
 59		uint16_t port;
 60	};
 61	
 62	// Los 4 callbacks de uxrCustomTransport: delegan 1:1 en microros-transport, como
 63	// vita-app/src/uxr_glue.c, pero contando lo que pasa.
 64	bool cb_open(uxrCustomTransport *t) {
 65		TransportArgs *a = (TransportArgs *)t->args;
 66		return a && microros_transport_open(a->ip, a->port);
 67	}
 68	bool cb_close(uxrCustomTransport *) {
 69		return microros_transport_close();
 70	}
 71	size_t cb_write(uxrCustomTransport *, const uint8_t *buf, size_t len, uint8_t *err) {
 72		size_t n = microros_transport_write(buf, len, err);
 73		g_diag.writes++;
 74		if (n == 0 || (err && *err)) {
 75			g_diag.write_errors++;
 76		}
 77		g_diag.write_bytes += (int)n;
 78		return n;
 79	}
 80	size_t cb_read(uxrCustomTransport *, uint8_t *buf, size_t len, int timeout, uint8_t *err) {
 81		size_t n = microros_transport_read(buf, len, (int32_t)timeout, err);
 82		g_diag.reads++;
 83		if (err && *err) {
 84			g_diag.read_errors++;
 85		}
 86		if (n > 0) {
 87			g_diag.read_packets++;
 88			g_diag.read_bytes += (int)n;
 89		}
 90		return n;
 91	}
 92	
 93	// Inicializa la red de la Vita ANTES de net_udp_init, guardando el código de cada paso (net_udp solo
 94	// devuelve "fallo"). El pool de sceNetInit sale del montón (memalign) y no del array estático de
 95	// net_udp.c: dentro de libgodot.so ese array vive en la imagen que mapea el cargador, no en memoria
 96	// normal de la app (hipótesis de G5 en hardware). net_udp_init acepta la red ya iniciada (EBUSY).
 97	void vita_net_init() {
 98	#ifdef VITA_ENABLED
 99		static void *pool = nullptr;
100		const int POOL = 1024 * 1024;
101		g_diag.rc_sysmodule = sceSysmoduleLoadModule(SCE_SYSMODULE_NET);
102		if (!pool) {
103			pool = memalign(4096, POOL);
104		}
105		if (pool) {
106			SceNetInitParam param;
107			param.memory = pool;
108			param.size = POOL;
109			param.flags = 0;
110			g_diag.rc_netinit = sceNetInit(&param);
111		} else {
112			g_diag.rc_netinit = -1; // sin memoria para el pool
113		}
114		g_diag.rc_netctl = sceNetCtlInit();
115	#endif
116		g_diag.rc_net_udp = net_udp_init();
117	}
118	
119	void read_netctl() {
120	#ifdef VITA_ENABLED
121		int state = -1;
122		if (sceNetCtlInetGetState(&state) >= 0) {
123			g_diag.netctl_state = state;
124		}
125		SceNetCtlInfo info;
126		if (sceNetCtlInetGetInfo(SCE_NETCTL_INFO_GET_IP_ADDRESS, &info) >= 0) {
127			g_diag.vita_ip = String(info.ip_address);
128		}
129	#endif
130	}
131	
132	// La MTU del transporte propio es 512 (UXR_CONFIG_CUSTOM_TRANSPORT_MTU): un mensaje mayor se fragmenta
133	// (solo en el stream fiable). Historial 16 y no 4 (vita-app): a 20 Hz, 4 huecos se llenaban antes de
134	// que llegara la confirmación del agente (G6). Cada hueco guarda un datagrama (<= MTU).
135	constexpr size_t RELIABLE_SLOT = UXR_CONFIG_CUSTOM_TRANSPORT_MTU;
136	constexpr uint16_t RELIABLE_HISTORY = 16;
137	constexpr size_t MAX_RX = 16 * 1024; // mensaje recibido más grande (reconstruido de fragmentos)
138	// Cabeceras XRCE dentro de un datagrama (mensaje + submensaje WRITE_DATA): lo que no cabe se fragmenta.
139	constexpr size_t XRCE_OVERHEAD = 24;
140	constexpr size_t BEST_EFFORT_BUF = UXR_CONFIG_CUSTOM_TRANSPORT_MTU;
141	constexpr int ENTITY_TIMEOUT_MS = 2000; // espera de la respuesta del agente al crear entidades
142	
143	// "geometry_msgs/msg/Twist" -> "geometry_msgs::msg::dds_::Twist_" (nombre DDS que usa ROS 2).
144	String dds_type_name(const String &p_ros) {
145		Vector<String> parts = p_ros.split("/");
146		if (parts.size() != 3) {
147			return String();
148		}
149		return parts[0] + "::" + parts[1] + "::dds_::" + parts[2] + "_";
150	}
151	
152	// XML de QoS para data_writer / data_reader (perfil XML de Fast DDS, que es lo que usa el agente).
153	String qos_xml(const Ref<RosQoS> &p_qos) {
154		bool best_effort = p_qos.is_valid() && p_qos->get_reliability() == RosQoS::BEST_EFFORT;
155		bool transient = p_qos.is_valid() && p_qos->get_durability() == RosQoS::TRANSIENT_LOCAL;
156		return String("<qos><reliability><kind>") + (best_effort ? "BEST_EFFORT" : "RELIABLE") +
157				"</kind></reliability><durability><kind>" + (transient ? "TRANSIENT_LOCAL" : "VOLATILE") +
158				"</kind></durability></qos>";
159	}
160	
161	String history_xml(const Ref<RosQoS> &p_qos) {
162		bool keep_all = p_qos.is_valid() && p_qos->get_history() == RosQoS::KEEP_ALL;
163		int depth = p_qos.is_valid() ? MAX(1, p_qos->get_depth()) : 10;
164		return String("<historyQos><kind>") + (keep_all ? "KEEP_ALL" : "KEEP_LAST") + "</kind><depth>" +
165				itos(depth) + "</depth></historyQos>";
166	}
167	
168	class XrceTransport : public RosTransport {
169		struct Endpoint {
170			uxrObjectId entity; // datawriter o datareader
171			bool reliable = true;
172		};
173	
174		uxrCustomTransport transport = {};
175		TransportArgs targs = {};
176		CharString agent_ip; // targs.ip apunta aquí: debe vivir mientras el transporte
177		uxrSession session = {};
178		bool transport_open = false;
179		bool session_open = false;
180	
181		uint8_t reliable_out_buf[RELIABLE_SLOT * RELIABLE_HISTORY];
182		uint8_t reliable_in_buf[RELIABLE_SLOT * RELIABLE_HISTORY];
183		uint8_t best_effort_out_buf[BEST_EFFORT_BUF];
184		uxrStreamId reliable_out = {}, reliable_in = {}, best_effort_out = {}, best_effort_in = {};
185	
186		uxrObjectId participant = {}, publisher = {}, subscriber = {};
187		HashMap<String, uxrObjectId> topics; // un topic DDS por nombre (crear dos con el mismo nombre falla)
188		HashMap<int, Endpoint> pubs;
189		HashMap<int, Endpoint> subs;
190		uint16_t next_entity = 1; // ids de objeto XRCE (12 bits)
191		int next_id = 1;
192	
193		uxrObjectId _new_object(uint8_t p_type) { return uxr_object_id(next_entity++, p_type); }
194	
195		// Bufferiza peticiones y espera a que el agente responda a todas. true si todas OK.
196		bool _wait(const uint16_t *p_req, int p_n, const String &p_what) {
197			uint8_t status[4] = {};
198			ERR_FAIL_COND_V(p_n > 4, false);
199			if (!uxr_run_session_until_all_status(&session, ENTITY_TIMEOUT_MS, p_req, status, p_n)) {
200				ERR_PRINT(vformat("ros2_vita/xrce: el agente rechazo o no respondio a %s (status %d %d %d %d).",
201						p_what, status[0], status[1], status[2], status[3]));
202				return false;
203			}
204			return true;
205		}
206	
207		// Devuelve el topic DDS ("rt" + nombre ROS), creándolo si hace falta.
208		bool _topic(const String &p_topic, const String &p_dds_type, uxrObjectId *r_id) {
209			const uxrObjectId *found = topics.getptr(p_topic);
210			if (found) {
211				*r_id = *found;
212				return true;
213			}
214			uxrObjectId id = _new_object(UXR_TOPIC_ID);
215			CharString xml = ("<dds><topic><name>rt" + p_topic + "</name><dataType>" + p_dds_type +
216					"</dataType></topic></dds>")
217									 .utf8();
218			uint16_t req = uxr_buffer_create_topic_xml(&session, reliable_out, id, participant, xml.get_data(), UXR_REPLACE);
219			if (!_wait(&req, 1, "crear el topic")) {
220				return false;
221			}
222			topics[p_topic] = id;
223			*r_id = id;
224			return true;
225		}
226	
227		static void _on_topic(uxrSession *, uxrObjectId p_object, uint16_t, uxrStreamId, ucdrBuffer *p_ub, uint16_t p_len, void *p_args) {
228			XrceTransport *self = (XrceTransport *)p_args;
229			g_diag.topic_callbacks++;
230			for (const KeyValue<int, Endpoint> &kv : self->subs) {
231				if (kv.value.entity.id == p_object.id && kv.value.entity.type == p_object.type) {
232					// Un mensaje reconstruido de fragmentos NO es contiguo: cada trozo sigue en su hueco del stream
233					// y ucdr salta de uno a otro con su callback de buffer lleno. Por eso se copia con
234					// ucdr_deserialize_array_uint8_t y no con p_ub->iterator (eso perdía todo /odom, G6).
235					static uint8_t buf[MAX_RX];
236					if (self->rx && p_len <= MAX_RX && ucdr_deserialize_array_uint8_t(p_ub, buf, p_len)) {
237						self->rx(self->rx_ctx, kv.key, buf, p_len);
238					} else {
239						g_diag.topic_dropped++;
240					}
241					return;
242				}
243			}
244		}
245	
246		// Fragmentación: cuando se llenan los slots del stream fiable, hay que enviarlos antes de seguir.
247		static bool _flush(uxrSession *p_session, void *) {
248			return uxr_run_session_time(p_session, 10);
249		}
250	
251	public:
252		Error start(const Dictionary &p_args) override {
253			ProjectSettings *ps = ProjectSettings::get_singleton();
254			String ip = p_args.has("agent_ip") ? String(p_args["agent_ip"])
255											   : String(ps->get_setting("ros/agent_ip", "127.0.0.1"));
256			int port = p_args.has("agent_port") ? String(p_args["agent_port"]).to_int()
257												: int(ps->get_setting("ros/agent_port", 8888));
258			int domain = p_args.has("domain_id") ? String(p_args["domain_id"]).to_int()
259												 : int(ps->get_setting("ros/domain_id", 0));
260			agent_ip = ip.utf8();
261			targs.ip = agent_ip.get_data();
262			targs.port = (uint16_t)port;
263			g_diag = XrceDiag();
264			g_diag.agent = vformat("%s:%d", ip, port);
265			print_line(vformat("ros2_vita/xrce: conectando con el agente %s:%d (dominio %d)...", ip, port, domain));
266	
267			// Abre el socket UDP (en la Vita: sceNetInit + sceNetCtlInit dentro de net_udp_init, docs/18 §4.3 A).
268			// false = sin framing: UDP ya delimita datagramas (el framing es para transportes serie).
269			uxr_set_custom_transport_callbacks(&transport, false, cb_open, cb_close, cb_write, cb_read);
270			g_diag.step = "iniciando red";
271			vita_net_init();
272			g_diag.step = "abriendo socket UDP";
273			bool opened = uxr_init_custom_transport(&transport, &targs);
274			read_netctl(); // net_udp_init ya inicializo sceNetCtl
275			ERR_FAIL_COND_V_MSG(!opened, ERR_CANT_CONNECT,
276					"ros2_vita/xrce: no se pudo abrir el socket UDP (red de la Vita sin conectar?).");
277			transport_open = true;
278			g_diag.step = "creando sesion XRCE";
279	
280			// Clave de cliente distinta en cada arranque: con una fija, dos clientes (la Vita y una prueba en
281			// el PC) se echaban el uno al otro de la sesión del agente. -p client_key:=N para fijarla.
282			uint32_t key = p_args.has("client_key") ? (uint32_t)String(p_args["client_key"]).to_int()
283													: (uint32_t)(OS::get_singleton()->get_ticks_usec() ^ (uint64_t)OS::get_singleton()->get_unix_time() * 2654435761u);
284			key = key ? key : 0xCAFE0005;
285			uxr_init_session(&session, &transport.comm, key);
286			uxr_set_topic_callback(&session, &XrceTransport::_on_topic, this);
287			bool created = uxr_create_session(&session);
288			read_netctl();
289			if (!created) {
290				g_diag.step = "sin respuesta del agente";
291				stop();
292				ERR_FAIL_V_MSG(ERR_CANT_CONNECT, vformat("ros2_vita/xrce: sin respuesta del agente en %s:%d "
293														 "(esta corriendo micro-ros-agent udp4 --port %d?).",
294														 ip, port, port));
295			}
296			session_open = true;
297			g_diag.step = "creando entidades";
298	
299			reliable_out = uxr_create_output_reliable_stream(&session, reliable_out_buf, sizeof(reliable_out_buf), RELIABLE_HISTORY);
300			reliable_in = uxr_create_input_reliable_stream(&session, reliable_in_buf, sizeof(reliable_in_buf), RELIABLE_HISTORY);
301			best_effort_out = uxr_create_output_best_effort_stream(&session, best_effort_out_buf, sizeof(best_effort_out_buf));
302			best_effort_in = uxr_create_input_best_effort_stream(&session);
303	
304			participant = _new_object(UXR_PARTICIPANT_ID);
305			publisher = _new_object(UXR_PUBLISHER_ID);
306			subscriber = _new_object(UXR_SUBSCRIBER_ID);
307			uint16_t req[3];
308			req[0] = uxr_buffer_create_participant_xml(&session, reliable_out, participant, (uint16_t)domain,
309					"<dds><participant><rtps><name>ros2_vita</name></rtps></participant></dds>", UXR_REPLACE);
310			req[1] = uxr_buffer_create_publisher_xml(&session, reliable_out, publisher, participant, "", UXR_REPLACE);
311			req[2] = uxr_buffer_create_subscriber_xml(&session, reliable_out, subscriber, participant, "", UXR_REPLACE);
312			if (!_wait(req, 3, "crear participante/publisher/subscriber")) {
313				stop();
314				return ERR_CANT_CREATE;
315			}
316			g_diag.step = "sesion abierta";
317			print_line("ros2_vita/xrce: sesion XRCE establecida.");
318			return OK;
319		}
320	
321		void stop() override {
322			if (session_open) {
323				uxr_delete_session(&session);
324				session_open = false;
325			}
326			if (transport_open) {
327				uxr_close_custom_transport(&transport);
328				transport_open = false;
329			}
330			topics.clear();
331			pubs.clear();
332			subs.clear();
333		}
334	
335		void poll() override {
336			if (session_open) {
337				uxr_run_session_time(&session, 0); // no bloquea: envía y vacía lo recibido
338			}
339		}
340	
341		int advertise(const String &p_topic, const String &p_type, const Ref<RosQoS> &p_qos) override {
342			ERR_FAIL_COND_V(!session_open, -1);
343			String dds = dds_type_name(p_type);
344			ERR_FAIL_COND_V_MSG(dds.is_empty(), -1, "ros2_vita/xrce: tipo ROS no valido: " + p_type);
345			uxrObjectId topic;
346			if (!_topic(p_topic, dds, &topic)) {
347				return -1;
348			}
349			Endpoint ep;
350			ep.entity = _new_object(UXR_DATAWRITER_ID);
351			ep.reliable = !(p_qos.is_valid() && p_qos->get_reliability() == RosQoS::BEST_EFFORT);
352			CharString xml = ("<dds><data_writer><topic><kind>NO_KEY</kind><name>rt" + p_topic + "</name><dataType>" + dds +
353					"</dataType>" + history_xml(p_qos) + "</topic>" + qos_xml(p_qos) + "</data_writer></dds>")
354									 .utf8();
355			uint16_t req = uxr_buffer_create_datawriter_xml(&session, reliable_out, ep.entity, publisher, xml.get_data(), UXR_REPLACE);
356			if (!_wait(&req, 1, "crear el datawriter de " + p_topic)) {
357				return -1;
358			}
359			pubs[next_id] = ep;
360			return next_id++;
361		}
362	
363		int subscribe(const String &p_topic, const String &p_type, const Ref<RosQoS> &p_qos) override {
364			ERR_FAIL_COND_V(!session_open, -1);
365			String dds = dds_type_name(p_type);
366			ERR_FAIL_COND_V_MSG(dds.is_empty(), -1, "ros2_vita/xrce: tipo ROS no valido: " + p_type);
367			uxrObjectId topic;
368			if (!_topic(p_topic, dds, &topic)) {
369				return -1;
370			}
371			Endpoint ep;
372			ep.entity = _new_object(UXR_DATAREADER_ID);
373			ep.reliable = !(p_qos.is_valid() && p_qos->get_reliability() == RosQoS::BEST_EFFORT);
374			CharString xml = ("<dds><data_reader><topic><kind>NO_KEY</kind><name>rt" + p_topic + "</name><dataType>" + dds +
375					"</dataType>" + history_xml(p_qos) + "</topic>" + qos_xml(p_qos) + "</data_reader></dds>")
376									 .utf8();
377			uint16_t req = uxr_buffer_create_datareader_xml(&session, reliable_out, ep.entity, subscriber, xml.get_data(), UXR_REPLACE);
378			if (!_wait(&req, 1, "crear el datareader de " + p_topic)) {
379				return -1;
380			}
381			// Pedir al agente que reenvíe todas las muestras de este datareader.
382			uxrDeliveryControl delivery = {};
383			delivery.max_samples = UXR_MAX_SAMPLES_UNLIMITED;
384			uxr_buffer_request_data(&session, reliable_out, ep.entity, ep.reliable ? reliable_in : best_effort_in, &delivery);
385			subs[next_id] = ep;
386			return next_id++;
387		}
388	
389		void unadvertise(int p_id) override {
390			const Endpoint *ep = pubs.getptr(p_id);
391			if (ep && session_open) {
392				uxr_buffer_delete_entity(&session, reliable_out, ep->entity);
393			}
394			pubs.erase(p_id);
395		}
396	
397		void unsubscribe(int p_id) override {
398			const Endpoint *ep = subs.getptr(p_id);
399			if (ep && session_open) {
400				uxr_buffer_cancel_data(&session, reliable_out, ep->entity);
401				uxr_buffer_delete_entity(&session, reliable_out, ep->entity);
402			}
403			subs.erase(p_id);
404		}
405	
406		Error publish(int p_id, const uint8_t *p_data, size_t p_len) override {
407			ERR_FAIL_COND_V(!session_open, ERR_UNCONFIGURED);
408			const Endpoint *ep = pubs.getptr(p_id);
409			ERR_FAIL_NULL_V(ep, ERR_DOES_NOT_EXIST);
410			ucdrBuffer ub;
411			const bool fits = p_len + XRCE_OVERHEAD <= UXR_CONFIG_CUSTOM_TRANSPORT_MTU;
412			if (!fits) {
413				// Mayor que un datagrama: solo el stream fiable sabe fragmentar.
414				ERR_FAIL_COND_V_MSG(!ep->reliable, ERR_OUT_OF_MEMORY,
415						vformat("ros2_vita/xrce: %d bytes no caben en un datagrama best effort (MTU %d).", (int)p_len, (int)BEST_EFFORT_BUF));
416				ERR_FAIL_COND_V_MSG(uxr_prepare_output_stream_fragmented(&session, reliable_out, ep->entity, &ub, p_len, &XrceTransport::_flush, nullptr) == UXR_INVALID_REQUEST_ID,
417						ERR_BUSY, "ros2_vita/xrce: stream fiable lleno; mensaje grande descartado.");
418			} else if (!ep->reliable || uxr_prepare_output_stream(&session, reliable_out, ep->entity, &ub, (uint32_t)p_len) == UXR_INVALID_REQUEST_ID) {
419				// Best effort, o el fiable está lleno (WiFi lenta, sin confirmar aún): mejor enviar sin garantía
420				// que bloquear o tirar el mensaje (para un teleop cuenta el último). La QoS DDS no cambia: la
421				// fiabilidad aquí es solo del tramo Vita <-> agente.
422				if (ep->reliable) {
423					g_diag.reliable_full++;
424				}
425				ERR_FAIL_COND_V(uxr_prepare_output_stream(&session, best_effort_out, ep->entity, &ub, (uint32_t)p_len) == UXR_INVALID_REQUEST_ID, ERR_BUSY);
426			}
427			ucdr_serialize_array_uint8_t(&ub, p_data, p_len);
428			return OK;
429		}
430	};
