54: bool uxr_prepare_reliable_buffer_to_write(
55:         uxrOutputReliableStream* stream,
56:         size_t length,
57:         ucdrBuffer* ub)
58: {
59:     bool available_to_write = false;
60:     uxrSeqNum seq_num = stream->last_written;
61:     size_t buffer_capacity = uxr_get_reliable_buffer_capacity(&stream->base);
62:     uint8_t* buffer = uxr_get_reliable_buffer(&stream->base, seq_num);
63:     size_t buffer_size = uxr_get_reliable_buffer_size(&stream->base, seq_num);
64: 
65:     uint16_t available_block_size = (uint16_t)(buffer_capacity - (uint16_t)(stream->offset + SUBHEADER_SIZE));
66:     size_t remaining_blocks = get_available_free_slots(stream);
67: 
68:     // Aligment required for inserting an XRCE subheader
69:     buffer_size += ucdr_alignment(buffer_size, 4);
70: 
71:     /* Check if the message fit in the current buffer */
72:     if (buffer_size + length <= buffer_capacity)
73:     {
74:         /* Check if there is space in the stream history to write */
75:         uxrSeqNum last_available = uxr_seq_num_add(stream->last_acknown, stream->base.history);
76:         available_to_write = (0 >= uxr_seq_num_cmp(seq_num, last_available));
77:         if (available_to_write)
78:         {
79:             size_t final_buffer_size = buffer_size + length;
80:             uxr_set_reliable_buffer_size(&stream->base, seq_num, final_buffer_size);
81:             ucdr_init_buffer_origin_offset(ub, buffer, (uint32_t)final_buffer_size, 0u, (uint32_t)buffer_size);
82:         }
83:     }
84:     /* Check if the message fit in a new empty buffer */
85:     else if (stream->offset + length <= buffer_capacity)
86:     {
87:         /* Check if there is space in the stream history to write */
88:         seq_num = uxr_seq_num_add(stream->last_written, 1);
89:         uxrSeqNum last_available = uxr_seq_num_add(stream->last_acknown, stream->base.history);
90:         available_to_write = (0 >= uxr_seq_num_cmp(seq_num, last_available));
91:         if (available_to_write)
92:         {
93:             buffer = uxr_get_reliable_buffer(&stream->base, seq_num);
94:             size_t final_buffer_size = stream->offset + length;
95:             uxr_set_reliable_buffer_size(&stream->base, seq_num, final_buffer_size);
96:             ucdr_init_buffer_origin_offset(ub, buffer, (uint32_t)final_buffer_size, 0u, stream->offset);
97:             stream->last_written = seq_num;
98:         }
99:     }
100:     /* Check if the message fit in a fragmented message */
101:     else if (length <= available_block_size * remaining_blocks)
102:     {
103:         /* Check if the current buffer free space is too small */
104:         if (buffer_size + (size_t)SUBHEADER_SIZE >= buffer_capacity)
105:         {
106:             seq_num = uxr_seq_num_add(seq_num, 1);
107:             buffer = uxr_get_reliable_buffer(&stream->base, seq_num);
108:             buffer_size = uxr_get_reliable_buffer_size(&stream->base, seq_num);
109:         }
110: 
111:         uint16_t first_fragment_size = (uint16_t)(buffer_capacity - (uint16_t)(buffer_size + SUBHEADER_SIZE));
112:         size_t remaining_size = length - first_fragment_size;
113:         size_t last_fragment_size = 0;
114:         uint16_t necessary_complete_blocks = 0;
115:         if (0 == (remaining_size % available_block_size))
116:         {
117:             last_fragment_size = available_block_size;
118:             necessary_complete_blocks = (uint16_t)((remaining_size / available_block_size));
119:         }
120:         else
121:         {
122:             last_fragment_size = remaining_size % available_block_size;
123:             necessary_complete_blocks = (uint16_t)((remaining_size / available_block_size) + 1);
124:         }
125: 
126:         available_to_write = necessary_complete_blocks <= remaining_blocks;
127:         if (available_to_write)
128:         {
129:             ucdrBuffer temp_ub;
130:             uint16_t fragment_size = first_fragment_size;
131:             for (uint16_t i = 0; i < necessary_complete_blocks; i++)
132:             {
133:                 ucdr_init_buffer_origin_offset(
134:                     &temp_ub,
135:                     uxr_get_reliable_buffer(&stream->base, seq_num),
136:                     buffer_capacity,
137:                     0u,
138:                     uxr_get_reliable_buffer_size(&stream->base, seq_num));
139:                 uxr_buffer_submessage_header(&temp_ub, SUBMESSAGE_ID_FRAGMENT, fragment_size, 0);
140:                 uxr_set_reliable_buffer_size(&stream->base, seq_num, buffer_capacity);
141:                 seq_num = uxr_seq_num_add(seq_num, 1);
142:                 fragment_size = available_block_size;
143:             }
144: 
145:             //  Prepare last fragment
146:             ucdr_init_buffer_origin_offset(
147:                 &temp_ub,
148:                 uxr_get_reliable_buffer(&stream->base, seq_num),
149:                 buffer_capacity,
150:                 0u,
151:                 uxr_get_reliable_buffer_size(&stream->base, seq_num));
152:             uxr_buffer_submessage_header(&temp_ub, SUBMESSAGE_ID_FRAGMENT, (uint16_t)last_fragment_size,
153:                     FLAG_LAST_FRAGMENT);
154:             uxr_set_reliable_buffer_size(&stream->base, seq_num,
155:                     stream->offset + (size_t)(SUBHEADER_SIZE) + last_fragment_size);
156: 
157:             // Prepare user buffer
158:             ucdr_init_buffer(
159:                 ub,
160:                 buffer + buffer_size + SUBHEADER_SIZE,
161:                 (uint32_t)(buffer_capacity - buffer_size - SUBHEADER_SIZE));
162:             ucdr_set_on_full_buffer_callback(ub, on_full_output_buffer, stream);
163:             stream->last_written = seq_num;
164:         }
165:     }
166: 
167:     return available_to_write;
168: }
